                    a >= b for a, b in zip(indices, indices[1:])):
                return finish("PROGRAM_ERROR", op, detail="invalid selected indices")
        if name in {"PUSH", "DUP"}:
            delta = 1
        elif name in {"DROP", "BRANCH", "FREE", "HALT"}:
