        elif name == "NOT":
            stack.append(int(not stack.pop()))
        elif name == "JUMP":
            next_pc = op[1]
        elif name == "BRANCH":
            if stack.pop():
                next_pc = op[1]
        elif name == "CALL":
            returns.append(next_pc)
            next_pc = op[1]
        elif name == "RETURN":
            next_pc = returns.pop()
        elif name == "ALLOC":
            n = stack.pop()
            regions[cursor] = n
            for address in range(cursor, cursor + n):
                memory[address] = 0
