    work: int = 0
    peak_cells: int = 0
    program_digest: str = ""
    input_digest: str = ""
    pc: int = 0
    next_instruction: tuple = ()
    next_cost: int = 0
    executed_by_pc: tuple = ()
    detail: str = ""


def integer(value):
