        elif name in {"ADD", "SUB", "EQ", "LT", "LE", "AND", "OR"}:
            b, a = stack.pop(), stack.pop()
            if name == "ADD":
                value = a + b
            elif name == "SUB":
                value = a - b
            elif name == "EQ":
                value = int(a == b)
            elif name == "LT":
                value = int(a < b)
            elif name == "LE":
                value = int(a <= b)
            elif name == "AND":
                value = int(bool(a) and bool(b))
            else:
                value = int(bool(a) or bool(b))
            stack.append(value)
        elif name == "NOT":
            stack.append(int(not stack.pop()))
        elif name == "JUMP":
            next_pc = op[1]
        elif name == "BRANCH":
            if stack.pop():
                next_pc = op[1]
        elif name == "CALL":
            returns.append(next_pc)
            next_pc = op[1]
        elif name == "RETURN":
            next_pc = returns.pop()
        elif name == "ALLOC":
            n = stack.pop()
            regions[cursor] = n
            for address in range(cursor, cursor + n):
                memory[address] = 0
            stack.append(cursor)
            cursor += n
            live_regions += n
        elif name == "FREE":
            base = stack.pop()
            n = regions.pop(base)
            for address in range(base, base + n):
                del memory[address]
